const items = $input.all().map(i => i.json);
const query = $('Webhook SIKAP').first().json.body.query || '';

// Hitung Agregat Pagu & Realisasi
let totalPagu = 0;
let totalRealisasi = 0;
const bidangStats = {
  BagTUM: { pagu: 0, realisasi: 0, roList: [] },
  Doklan: { pagu: 0, realisasi: 0, roList: [] },
  Gakkum: { pagu: 0, realisasi: 0, roList: [] }
};

for (const row of items) {
  const p = parseFloat(String(row.pagu || '0').replace(/[^0-9,-]/g, '').replace(',', '.')) || 0;
  const r = parseFloat(String(row.realisasi || '0').replace(/[^0-9,-]/g, '').replace(',', '.')) || 0;
  totalPagu += p;
  totalRealisasi += r;

  const b = row.bidang_bagian || 'BagTUM';
  if (bidangStats[b]) {
    bidangStats[b].pagu += p;
    bidangStats[b].realisasi += r;
    bidangStats[b].roList.push({
      kode: row.kode_ro,
      nama: row.nama_ro,
      pagu: p,
      realisasi: r,
      persentase: p > 0 ? ((r / p) * 100).toFixed(2) : '0'
    });
  }
}

const totalPct = totalPagu > 0 ? ((totalRealisasi / totalPagu) * 100).toFixed(2) : '0';

let responseMessage = `Analisis Data SIKAP: Total Pagu Rp ${(totalPagu/1e9).toFixed(2)} M, Realisasi Rp ${(totalRealisasi/1e9).toFixed(2)} M (${totalPct}%).`;
if (query.toLowerCase().includes('bagtum') || query.toLowerCase().includes('tata usaha')) {
  responseMessage = `Bagian Tata Usaha (BagTUM) memiliki 9 RO dengan total serapan ${((bidangStats.BagTUM.realisasi/bidangStats.BagTUM.pagu)*100).toFixed(2)}%. Layanan Manajemen Keuangan mencapai 99.98%.`;
} else if (query.toLowerCase().includes('gakkum') || query.toLowerCase().includes('patnal')) {
  responseMessage = `Bidang Penegakan Hukum & Kepatuhan Internal memiliki 7 RO dengan serapan saat ini ${((bidangStats.Gakkum.realisasi/bidangStats.Gakkum.pagu)*100).toFixed(2)}%.`;
} else if (query.toLowerCase().includes('doklan')) {
  responseMessage = `Bidang Doklan memiliki 1 RO utama dengan realisasi ${((bidangStats.Doklan.realisasi/bidangStats.Doklan.pagu)*100).toFixed(2)}%.`;
}

return [{
  json: {
    status: 'success',
    action: 'query',
    query: query,
    message: responseMessage,
    data: {
      total_pagu: totalPagu,
      total_realisasi: totalRealisasi,
      total_sisa: totalPagu - totalRealisasi,
      persentase: parseFloat(totalPct),
      bidang: [
        { nama: 'BagTUM', pagu: bidangStats.BagTUM.pagu, realisasi: bidangStats.BagTUM.realisasi, persentase: parseFloat(((bidangStats.BagTUM.realisasi/bidangStats.BagTUM.pagu)*100).toFixed(2)) },
        { nama: 'Doklan', pagu: bidangStats.Doklan.pagu, realisasi: bidangStats.Doklan.realisasi, persentase: parseFloat(((bidangStats.Doklan.realisasi/bidangStats.Doklan.pagu)*100).toFixed(2)) },
        { nama: 'Gakkum', pagu: bidangStats.Gakkum.pagu, realisasi: bidangStats.Gakkum.realisasi, persentase: parseFloat(((bidangStats.Gakkum.realisasi/bidangStats.Gakkum.pagu)*100).toFixed(2)) }
      ]
    }
  }
}];
